public static int calculateTimeNeeded(int N) {
    // Keep swapping the left and right neighbors until the original order is restored
    int timeNeeded = 0;
    while (N > 1) {
        timeNeeded++;
        N = N / 2 + N % 2;
    }
    return timeNeeded;
}

