public List<List<Integer>> permute(int[] nums) {
        List<List<Integer>> permutations = new ArrayList<>();
        if (nums.length == 0) {
            return permutations;
        }
        Arrays.sort(nums);
        int n = nums.length;
        int[] indices = new int[n];
        for (int i = 0; i < n; i++) {
            indices[i] = i;
        }
        List<Integer> permutation = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            permutation.add(nums[indices[i]]);
        }
        permutations.add(permutation);
        while (true) {
            int i = n - 1;
            while (i > 0 && indices[i] - indices[i - 1] == 1) {
                i--;
            }
            if (i == 0) {
                break;
            }
            int j = i - 1;
            int t = indices[i];
            indices[i] = indices[j];
            indices[j] = t;
            permutation = new ArrayList<>();
            for (i = 0; i < n; i++) {
                permutation.add(nums[indices[i]]);
            }
            permutations.add(permutation);
        }
        return permutations;
    }

