public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (int i = 0; i < strings.size() - 1; i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            if (strings.get(i).contains(strings.get(j)) || strings.get(j).contains(strings.get(i))) {
                return Math.max(strings.get(i).length(), strings.get(j).length());
            }
        }
    }
    return maxLength;
}

