public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    if (strings.size() == 1) {
        return 1;
    }
    int inverseCount = 0;
    for (String s : strings) {
        if (s.length() < inverseCount) {
            continue;
        }
        String inverse = new StringBuilder(s).reverse().toString();
        for (String t : strings) {
            if (s.equals(t)) {
                continue;
            }
            if (s.contains(t)) {
                return Math.max(inverseCount, t.length());
            } else if (inverse.contains(t)) {
                inverseCount = Math.max(inverseCount, s.length());
                return inverseCount;
            }
        }
    }
    return 0;
}

