        graph.addEdge(edge[0], edge[1]);
    }

    // Define a function to compute the minimum distance from the root node (node 0) to a given node
    Function<Integer, Integer> dfs = new Function<Integer, Integer>() {
        @Override
        public Integer apply(Integer node) {
            // If the distance to the root node is already known, return it
            if (distance[node] != Integer.MAX_VALUE) {
                return distance[node];
            }

            // Otherwise, compute the minimum distance from the root node to each child node
            int minDistance = Integer.MAX_VALUE;
            for (Integer child : graph.getNeighbors(node)) {
                int childDistance = dfs.apply(child);
                if (childDistance < minDistance) {
                    minDistance = childDistance;
                }
