            // Add the weight of the current node to the minimum distance
            minDistance += hasApple[node] ? 1 : 0;

            // Return the minimum distance
            distance[node] = minDistance;
            return minDistance;
        }
    };

    // Compute the minimum distance from the root node to each node
    dfs.apply(0);

    // Return the minimum distance from the root node to the last node
    return distance[n - 1];
}

