        int currentAverage = leftSum / (i + 1);
        if (currentAverage == average) {
            count++;
        }
    }
    if (count > 1) {
        return true;
    }

    count = 0;
    int rightSum = 0;
    for (int i = nums.length - 1; i >= 0; i--) {
        rightSum += nums[i];
        int currentAverage = rightSum / (nums.length - i);
        if (currentAverage == average) {
            count++;
        }
    }
    return count > 1;
}

