public static int largestRectangleArea(int[] heights) {
    if (heights.length == 0) {
        return 0;
    }

    // Create a stack to keep track of the current rectangle boundaries
    Deque<Integer> stack = new ArrayDeque<>();
    int maxArea = 0;

    for (int i = 0; i < heights.length; i++) {
        int currentHeight = heights[i];

        // If the current height is greater than the height of the previous rectangle,
        // add it to the stack and update the max area
        if (currentHeight > heights[stack.peekLast()]) {
            stack.addLast(i);
            maxArea = Math.max(maxArea, currentHeight * i);
        } else {
            // If the current height is less than or equal to the height of the previous rectangle,
            // remove the previous rectangle from the stack and update the max area
            while (!stack.isEmpty() && heights[stack.peekLast()] >= currentHeight) {
                int previousHeight = heights[stack.removeLast()];
                maxArea = Math.max(maxArea, previousHeight * (i - stack.peekLast()));
            }

            // Add the current rectangle to the stack
            stack.addLast(i);
        }
    }

    // Return the maximum area
    return maxArea;
}

