public static int minPerfectSquareSum(int n) {
    // Initialize a variable to store the minimum number of perfect square numbers
    int minNumber = Integer.MAX_VALUE;

    // Loop through all possible perfect square numbers less than or equal to n
    for (int i = 1; i * i <= n; i++) {
        // Get the sum of the current perfect square number and the remaining amount
        int sum = i * i + (n - i * i);

        // If the sum is equal to the target amount, update the minimum number
        if (sum == n) {
            minNumber = 1;
            break;
        }

        // If the sum is less than the target amount, recursively call the function with the remaining amount
        if (sum < n) {
            int minNumberRecursive = minPerfectSquareSum(n - sum);
            if (minNumberRecursive < minNumber) {
                minNumber = minNumberRecursive + 1;
            }
        }
    }

    return minNumber;
}

